type entry[V any] struct{ v V; at time.Time }
type Cache[K comparable, V any] struct{ mu sync.RWMutex; m map[K]entry[V]; ttl time.Duration }
func (c *Cache[K, V]) Get(k K) (V, bool) {       // miss also covers expiry
	c.mu.RLock()
	e, ok := c.m[k]
	c.mu.RUnlock()
	if ok && time.Since(e.at) <= c.ttl {
		return e.v, true
	}
	var zero V
	return zero, false                           // Set: mu.Lock(); m[k] = entry{v: v, at: time.Now()}
}

